import{_ as e,a as r,o as d,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"List Returnable Items","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-returnable-items","title":"List Returnable Items","description":"List the return-eligible items of one of the authenticated customer's orders, with the quantity caps the store enforces.","request":"GET /api/shop/returnable-items?order_id=45\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"[\\n  {\\n    \\"orderItemId\\": 78,\\n    \\"productId\\": 1,\\n    \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n    \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n    \\"type\\": \\"simple\\",\\n    \\"urlKey\\": \\"coastal-breeze-mens-blue-zipper-hoodie\\",\\n    \\"price\\": 100,\\n    \\"baseImageUrl\\": \\"https://example.com/storage/product/1/hoodie.webp\\",\\n    \\"qtyOrdered\\": 2,\\n    \\"currentQuantity\\": 2,\\n    \\"forReturnQuantity\\": 2,\\n    \\"forCancelQuantity\\": 0,\\n    \\"rmaQuantity\\": 0,\\n    \\"rmaReturnPeriod\\": 30\\n  }\\n]\\n","commonErrors":[{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"401 Unauthorized","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"},{"error":"404 Not Found","cause":"The order does not exist or is not owned by the authenticated customer","solution":"Only order IDs belonging to the logged-in customer can be queried"}]}]},"headers":[],"relativePath":"api/rest-api/shop/returns/list-returnable-items.md","filePath":"api/rest-api/shop/returns/list-returnable-items.md","lastUpdated":1787725411000}`),o={name:"api/rest-api/shop/returns/list-returnable-items.md"};function n(i,t,s,c,u,h){return d(),r("div",null,t[0]||(t[0]=[a('<h1 id="list-returnable-items" tabindex="-1">List Returnable Items <a class="header-anchor" href="#list-returnable-items" aria-label="Permalink to &quot;List Returnable Items&quot;">​</a></h1><p>List the items of one of the customer&#39;s orders that are <strong>still eligible for return</strong> — within their return window and not already fully returned or canceled. Each row carries the trusted quantity caps the store enforces when a return is raised (<code>forReturnQuantity</code>, <code>forCancelQuantity</code>, <code>currentQuantity</code>), so a client can present the correct maximum. Use these rows to pick the <code>orderItemId</code> and quantity for <a href="/api/rest-api/shop/returns/create-return.html"><code>POST /api/shop/returns</code></a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/returnable-items</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>order_id</code></td><td>integer</td><td>Yes</td><td>Id of the order to list returnable items for. Must belong to the authenticated customer.</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>The response is a plain JSON array. Each item is a returnable-item object.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderItemId</code></td><td>integer</td><td>Id of the order item — use this when raising a return.</td></tr><tr><td><code>productId</code></td><td>integer</td><td>Id of the product.</td></tr><tr><td><code>sku</code></td><td>string</td><td>Product SKU.</td></tr><tr><td><code>name</code></td><td>string</td><td>Product name.</td></tr><tr><td><code>type</code></td><td>string</td><td>Product type, e.g. <code>simple</code>.</td></tr><tr><td><code>urlKey</code></td><td>string</td><td>Product URL key.</td></tr><tr><td><code>price</code></td><td>number</td><td>Item price.</td></tr><tr><td><code>baseImageUrl</code></td><td>string</td><td>URL of the product&#39;s base image.</td></tr><tr><td><code>qtyOrdered</code></td><td>integer</td><td>Quantity originally ordered.</td></tr><tr><td><code>currentQuantity</code></td><td>integer</td><td>Quantity currently eligible to act on.</td></tr><tr><td><code>forReturnQuantity</code></td><td>integer</td><td>Maximum units that can be returned.</td></tr><tr><td><code>forCancelQuantity</code></td><td>integer</td><td>Maximum units that can be canceled.</td></tr><tr><td><code>rmaQuantity</code></td><td>integer</td><td>Units already placed into a return.</td></tr><tr><td><code>rmaReturnPeriod</code></td><td>integer</td><td>Return window in days.</td></tr></tbody></table><h2 id="status-codes" tabindex="-1">Status Codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>200 OK</code></td><td>Returnable items retrieved.</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid storefront key.</td></tr><tr><td><code>403 Forbidden</code></td><td>Missing or invalid customer Bearer token.</td></tr><tr><td><code>404 Not Found</code></td><td>The order does not exist or is not the customer&#39;s.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/returns/list-return-reasons.html">List Return Reasons</a> — the reason ids to choose from</li><li><a href="/api/rest-api/shop/returns/create-return.html">Raise a Return</a> — raise a return against one order item</li><li><a href="/api/rest-api/shop/returns/">Returns Overview</a> — the returns menu overview, including the settings that gate it</li></ul>',17)]))}const m=e(o,[["render",n]]);export{p as __pageData,m as default};
